  /** Is that spell already in their book. */
  function knowsSpell(state, name) {
    var s = state || fresh();
    var known = (s.spells && s.spells.known) || [];
    return known.indexOf(name) !== -1;
  }

  /** Every perk this character holds right now, from state alone. */
