      var id = near[i];
      var base = '';
      try { base = String(mp.get(id, 'baseDesc') || ''); } catch (e) { continue; }
      if (!P.has(CROPS, base)) { continue; }
      var p = null;
      try { p = mp.get(id, 'pos'); } catch (e) { continue; }
